function QueryProvider(props: ParentProps) {
  const client = new QueryClient({
    defaultOptions: {
      queries: {
        refetchOnReconnect: false,
        refetchOnMount: false,
        refetchOnWindowFocus: false,
      },
    },
  })
  return <QueryClientProvider client={client}>{props.children}</QueryClientProvider>
}

function BodyDesignClass() {
  createRenderEffect(() => {
    if (typeof document === "undefined") return

    document.documentElement.toggleAttribute("data-new-layout", true)
    document.body.toggleAttribute("data-new-layout", true)
    syncThemeBackground()
    // The HTML shells ship the body with the pre-JS text class; the app font replaces it.
    document.body.classList.remove("text-12-regular")
    document.body.classList.add("font-(family-name:--font-family-text)", "text-[13px]", "font-[440]")
  })

  return null
}

// Server-agnostic providers shared across every route. These live in the shared
// shell (router root) so they stay mounted regardless of the active server/route.
function SharedProviders(props: ParentProps) {
  return (
    <>
      <BodyDesignClass />
      <CommandProvider>
        <DesktopCommands />
        {props.children}
      </CommandProvider>
    </>
  )
}

function DesktopCommands() {
  const command = useCommand()
  const language = useLanguage()
  const platform = usePlatform()

  command.register("desktop", () => {
    const commands: CommandOption[] = []
    if (platform.platform === "desktop" && platform.exportDebugLogs) {
      commands.push({
        id: "logs.export",
        title: language.t("command.logs.export"),
        category: language.t("command.category.settings"),
        onSelect: () => {
          void platform.exportDebugLogs?.().catch((error: unknown) =>
            showToast({
              variant: "error",
              title: language.t("orchestra.shell.logs.exportFailed"),
              description: errorMessage(error, language.t("common.requestFailed")),
            }),
          )
        },
      })
    }
    return commands
  })

  return null
}

function NewAppLayout(props: ParentProps<{ serverScoped?: JSX.Element }>) {
  return (
    <SelectedServerProviders>
      <LayoutProvider>
        {props.serverScoped}
        <ModelsProvider>
          <NewLayout>{props.children}</NewLayout>
        </ModelsProvider>
      </LayoutProvider>
    </SelectedServerProviders>
  )
}

function HomeServerProviders() {
  const layout = useLayout()
  const global = useGlobal()
  const server = useServer()
  const owner = createMemo(
    () => {
      const selection = layout.home.selection()
      const conn =
        global.servers.list().find((item) => ServerConnection.key(item) === selection.server) ?? server.current
      if (!conn) return
      const directory = ServerConnection.key(conn) === selection.server ? selection.directory : undefined
      return { key: `${ServerConnection.key(conn)}\0${directory ?? ""}`, conn, directory }
    },
    undefined,
    { equals: (a, b) => a?.key === b?.key },
  )
  return (
    <Show when={owner()} keyed>
      {(owner) => (
        <ServerSDKProvider server={() => owner.conn}>
          <ServerSyncProvider server={() => owner.conn}>
            <ModelsProvider directory={() => owner.directory}>
              <NewHome />
            </ModelsProvider>
          </ServerSyncProvider>
        </ServerSDKProvider>
      )}
    </Show>
  )
}

// The draft page only renders the prompt composer, so it drops TerminalProvider.
// FileProvider and CommentsProvider stay because PromptInput uses file search and comment context.
function DraftProviders(props: ParentProps) {
  return (
    <FileProvider>
      <PromptProvider>
        <CommentsProvider>{props.children}</CommentsProvider>
      </PromptProvider>
    </FileProvider>
  )
}

export function AppBaseProviders(
  props: ParentProps<{
    locale?: Locale
    onNativeTranslations?: Parameters<typeof LanguageProvider>[0]["onNativeTranslations"]
  }>,
) {
  makeEventListener(window, "unhandledrejection", logUnhandledRejection)
  return (
    <MetaProvider>
      <Font />
      <ThemeProvider
        onThemeApplied={(_, mode, scheme) => {
          void window.api?.setTitlebar?.({ mode, scheme })
        }}
      >
        <OrchestraPaletteProvider>
          <LanguageProvider locale={props.locale} onNativeTranslations={props.onNativeTranslations}>
            <UiI18nBridge>
              <ErrorBoundary
                fallback={(error) => {
                  Sentry.captureException(error)
                  return <ErrorPage error={error} />
                }}
              >
                <QueryProvider>
                  <WslServersProvider>
                    <ModelPreferencesProvider>
                      <DialogProvider>
                        <FileComponentProvider component={File}>{props.children}</FileComponentProvider>
                      </DialogProvider>
                    </ModelPreferencesProvider>
                  </WslServersProvider>
                </QueryProvider>
              </ErrorBoundary>
            </UiI18nBridge>
          </LanguageProvider>
        </OrchestraPaletteProvider>
      </ThemeProvider>
    </MetaProvider>
  )
}

function ConnectionGate(props: ParentProps<{ disableHealthCheck?: boolean; startup?: Promise<void> }>) {
  const server = useServer()
  const checkServerHealth = useCheckServerHealth()

  const [checkMode, setCheckMode] = createSignal<"blocking" | "background">("blocking")

  // performs repeated health check with a grace period for
  // non-http connections, otherwise fails instantly
  const [startupHealthCheck, healthCheckActions] = createResource(() =>
    props.disableHealthCheck
      ? true
      : Effect.gen(function* () {
          if (!server.current) return true
          const { http, type } = server.current

          while (true) {
            const res = yield* Effect.promise(() => checkServerHealth(http))
            if (res.healthy) return true
            if (checkMode() === "background" || type === "http") return false
            // A sidecar that is still starting refuses at once; without a pause this loop asks it continuously.
            yield* Effect.sleep("500 millis")
          }
        }).pipe(
          Effect.timeoutOrElse({ duration: "10 seconds", orElse: () => Effect.succeed(false) }),
          Effect.ensuring(Effect.sync(() => setCheckMode("background"))),
          Effect.runPromise,
        ),
  )
  const checking = createMemo(
    () => checkMode() === "blocking" && ["unresolved", "pending"].includes(startupHealthCheck.state),
  )
  const [startup] = createResource(async () => {
    if (!props.startup) return true
    await props.startup.catch((error) => {
      console.error("[startup] startup gate failed", error)
    })
    return true
  })
  const startupChecking = createMemo(
    () => startupHealthCheck.latest === true && ["unresolved", "pending"].includes(startup.state),
  )
  const loading = createMemo(() => checking() || startupChecking())

  return (
    <>
      <Show when={!checking()}>
        <Show
          when={startupHealthCheck.latest}
          fallback={
            <ConnectionError
              onRetry={() => {
                if (checkMode() === "background") void healthCheckActions.refetch()
              }}
              onServerSelected={(key) => {
                setCheckMode("blocking")
                server.setActive(key)
                void healthCheckActions.refetch()
              }}
            />
          }
        >
          {props.children}
        </Show>
      </Show>
      <Show when={loading()}>
        <div class="fixed inset-0 z-[9999] bg-background-base" data-tauri-drag-region data-app-loading />
      </Show>
    </>
  )
}

function ServerKey(props: ParentProps) {
  const server = useServer()
  return (
    <Show when={server.key} keyed>
      {props.children}
    </Show>
  )
}

export function AppInterface(props: {
  children?: JSX.Element
  defaultServer: ServerConnection.Key
  canonicalLocalServer?: ServerConnection.Key
  servers?: Array<ServerConnection.Any>
  router?: Component<BaseRouterProps>
  disableHealthCheck?: boolean
  startup?: Promise<void>
  serverScoped?: JSX.Element
}) {
  // The visual new layout lives in the router root so it remains mounted across
  // route changes. Draft and session routes override only their server-bound data
  // providers beneath it.
  const ServerShell = (shellProps: ParentProps) => {
    const settings = useSettings()
    return (
      <SharedProviders>
        <JanitorProvider enabled={settings.general.janitorEnabled}>
          {props.children}
          {shellProps.children}
          <JanitorWidget />
        </JanitorProvider>
      </SharedProviders>
    )
  }

  return (
    <ServerProvider
      defaultServer={props.defaultServer}
      canonicalLocalServer={props.canonicalLocalServer}
      servers={props.servers}
    >
      <GlobalProvider>
        <SettingsProvider>
          <ConnectionGate disableHealthCheck={props.disableHealthCheck} startup={props.startup}>
            <Dynamic
              component={props.router ?? Router}
              root={(routerProps) => (
                <TabsProvider>
                  <PermissionProvider>
                    <NotificationProvider>
                      <ServerShell>
                        <NewAppLayout serverScoped={props.serverScoped}>{routerProps.children}</NewAppLayout>
                      </ServerShell>
                    </NotificationProvider>
                  </PermissionProvider>
                </TabsProvider>
              )}
            >
              <Routes />
            </Dynamic>
          </ConnectionGate>
        </SettingsProvider>
      </GlobalProvider>
    </ServerProvider>
  )
}

function Routes() {
  return (
    <>
      <Route component={(routeProps) => <SelectedServerProviders>{routeProps.children}</SelectedServerProviders>}>
        <Route path="/:dir" component={DirectoryLayout}>
          <Route path="/" component={() => <Navigate href="session" />} />
          <Route path="/session/:id?" component={SessionRoute} />
        </Route>
      </Route>
      <Route path="/" component={HomeServerProviders} />
      <Route path="/:dir/session/:id" component={NewLayoutLegacySessionRedirect} />
      <Route path="/server/:serverKey/session/:id" component={TargetSessionRoute} />
      <Route path="/orchestra/:chapter/*rest" component={OrchestraChapterRoute} />
      <Route path="/new-session" component={DraftRoute} />
    </>
  )
}

function NewLayoutLegacySessionRedirect() {
  const server = useServer()
  const tabs = useTabs()
  const params = useParams<{ id: string }>()

  return (
    <Show when={tabs.ready()}>
      <Navigate
        href={sessionHref(
          legacySessionServer(
            tabs.store.filter((item) => item.type === "session"),
            params.id,
            server.key,
          ),
          params.id,
        )}
      />
    </Show>
  )
}

import { createSimpleContext } from "@orchestra/ui/context"
import type { AsyncStorage, SyncStorage } from "@solid-primitives/storage"
import type { Accessor } from "solid-js"
import type { DesktopMenuAction } from "../desktop-menu"
import { ServerConnection } from "./server"
import type { WslServersPlatform } from "../wsl/types"
import type { UpdaterPlatform } from "../updater"
import type { DraftStore } from "@/utils/draft-store"
import type { NativeTitlebarFrame } from "../native-titlebar"
import type {
  LiveHotkey,
  LiveHotkeyAction,
  LivePermission,
  LiveReadiness,
  LiveRunState,
  LiveSettings,
  LiveSource,
} from "../live"
export type { NativeTitlebarFrame } from "../native-titlebar"

export type {
  LiveHotkey,
  LiveHotkeyAction,
  LivePermission,
  LiveReadiness,
  LiveRunState,
  LiveSettings,
  LiveSource,
} from "../live"

export type LiveSeatPlatform = {
  // "permission": the microphone is denied. With only system audio denied the meeting starts on the microphone.
  start(title?: string): Promise<
    | { ok: true; meetingID: string }
    | { ok: false; reason: "running" | "no-key" | "server" | "capture" | "permission" }
  >
  stop(): Promise<void>
  running(): Promise<boolean>
  // Write-only: the key is never read back; an empty key clears it.
  hasTranscriptionKey(): Promise<boolean>
  setTranscriptionKey(key: string): Promise<void>
  getContentProtection(): Promise<boolean>
  setContentProtection(enabled: boolean): Promise<void>
  // Re-checked on every call; the renderer calls it on window focus.
  readiness(): Promise<LiveReadiness>
  // Shows the system prompt when "needed"; opens the matching System Settings pane when "denied".
  requestPermission(source: LiveSource): Promise<LivePermission>
  // RMS 0..1 at about 15 Hz while running or while subscribed. Returns unsubscribe.
  onLevels(listener: (levels: Record<LiveSource, number>) => void): () => void
  // Every renderer window gets the same run-state events. Returns unsubscribe.
  runState(): Promise<LiveRunState>
  onRunState(listener: (state: LiveRunState) => void): () => void
  rename(meetingID: string, title: string): Promise<void>
  // A partial write is merged; both return the full object.
  getSettings(): Promise<LiveSettings>
  setSettings(patch: Partial<LiveSettings>): Promise<LiveSettings>
  // "conflict": another app or another of our actions holds the accelerator.
  getHotkeys(): Promise<LiveHotkey[]>
  setHotkey(
    action: LiveHotkeyAction,
    accelerator: string,
  ): Promise<{ ok: true } | { ok: false; reason: "conflict" | "invalid" }>
  resetHotkeys(): Promise<LiveHotkey[]>
}

type PickerPaths = string | string[] | null
type OpenDirectoryPickerOptions = { title?: string; multiple?: boolean }
type OpenAttachmentPickerOptions = {
  title?: string
  multiple?: boolean
  accept?: string[]
  extensions?: string[]
  defaultPath?: string
}
type SaveFilePickerOptions = { title?: string; defaultPath?: string }
type PlatformName = "web" | "desktop"
type DesktopOS = "macos" | "windows" | "linux"

export type FatalRendererErrorLog = {
  error: string
  url: string
  version?: string
  platform: PlatformName
  os?: DesktopOS
}

type PlatformBase = {
  /** Native caption area in CSS viewport coordinates; omitted geometry restores default placement. */
  setTitlebarFrame?(frame?: NativeTitlebarFrame): Promise<void>
  /** App version */
  version?: string

  /** Open a web or mail URL in the default system application */
  openExternal(url: string): void

  /** Open a local path in a local app (desktop only) */
  openPath?(path: string, app?: string): Promise<void>

  /** Open a local file URL in its default app (desktop only) */
  openLocalFile?(url: string): void

  /** Reveal a local path in the system file manager; false when the path does not exist (desktop only) */
  revealPath?(path: string): Promise<boolean>

  /** Restart the app  */
  restart(): Promise<void>

  /**
   * Run `handler` before this window closes or the app quits, for work the page must save first. The desktop waits
   * for it at most 3 s, then closes anyway (desktop only). Returns a function that unregisters it.
   */
  onBeforeUnload?(handler: () => Promise<void>): () => void

  /** Send a system notification */
  notify(title: string, description?: string, onClick?: () => void): Promise<void>

  /** Open a native attachment picker and read selected files sequentially (desktop only) */
  openAttachmentPickerDialog?(
    opts: OpenAttachmentPickerOptions,
    onFile: (file: File) => Promise<unknown>,
  ): Promise<void>

  /** Resolve the native source path for a desktop File. */
  getPathForFile?(file: File): string

  /** Open a native save file picker dialog (desktop only) */
  saveFilePickerDialog?(opts?: SaveFilePickerOptions): Promise<string | null>

  /** Save raw response bytes with backpressure; cancellation rejects with AbortError. */
  downloadResponse?(response: Response, filename: string): Promise<void>

  /** Storage mechanism, defaults to localStorage */
  storage?: (name?: string) => SyncStorage | AsyncStorage

  /** Prompt drafts, history, and their blobs. */
  draftStore?: DraftStore

  /** Stable platform window identity for window-scoped persistence */
  windowID?: string

  /** Application-global desktop updater */
  updater?: UpdaterPlatform

  /** Fetch override */
  fetch?: typeof fetch

  /** Get the configured default server URL (platform-specific) */
  getDefaultServer?(): Promise<ServerConnection.Key | null>

